Suppose that the assumptions of D.4 hold. Suppose that $n > A_{\lambda,\tau}$ with $A_{\lambda,\tau}$ defined in Eq.~(eq:FS_thm_16_const). Suppose Assumptions~2.2 hold.  Suppose that $\tilde{n} \geq 1$ satisfies Eq. (eq:m_sufficient_large). Let $\lambda \asymp n^{-1}$ and 
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*} Then, with $P^{n+\tilde{n}}$-probability $\geq 1-  34e^{-\tau}$, we have
\begin{align*}
    \left\|T\left(\left[\bar{f}_{\lambda}\right] - \left[\hat{f}_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})} \lesssim \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}

Suppose Assumptions~2.2, 2.3, 4.1, 4.2 and 4.3 in the main text hold. 
Let $\lambda = n^{-1}$ and 
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*} Fix an arbitrary $p>0$. Then with probability $\geq 1-5e^{-\tau}$, for sufficiently large $n\geq 1$, the following bound holds
    \begin{align*}
        \|\bar{f}_{\lambda}\|^2_{\mathcal{H}_{\gamma_x,\gamma_o}}\lesssim \tau n^{\frac{1 + \frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1 + (2 + \frac{d_o}{s_o})(\frac{s_x}{d_x} + \eta_1)} + p}.
    \end{align*}

Suppose Assumptions~2.2, 2.3, 4.1, 4.2 and 4.3 in the main text hold. 
Let $\lambda = n^{-1}$ and 
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*} Then we have 
\begin{align*}
    \lambda \| f_\lambda\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 + \left\|T\left(f_{\ast} - \left[f_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})}^2 \leq C n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}},
\end{align*}
for some constant $C>0$ independent of $n$.

Fix $\tau\geq 1$. Suppose that the assumptions of D.4 hold. Suppose that $n > A_{\lambda,\tau}$ with $A_{\lambda,\tau}$ defined in Eq.~(eq:FS_thm_16_const), and $\tilde{n} \geq 1$ satisfies Eq. (eq:m_sufficient_large) in the main text. We have with $P^{n+\tilde{n}}$-probability $\geq 1 - 28e^{-\tau}$, the following inequality holds
\begin{align*}
    &\left\|T [\hat{f}_{\lambda}] - T [\bar{f}_{\lambda}] \right\|_{L^2(P_{ZO})}\\ &\lesssim \tau \lambda^{-\frac{1}{2}} \left(\frac{\left\|\hat{F}_{\xi}-F_*\right\|_{\mathcal{G}}}{\sqrt{n}}+\left\|\left[F_*-\hat{F}_{\xi}\right]\right\|_{L^2\left(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x}\right)}\right) \left(1 + \|\bar{f}_{\lambda}\|_{\mathcal{H}_{\gamma_x,\gamma_o}}\right).
\end{align*}
Under the same probabilistic event, the bounds in D.4 also hold.

Fix $\tau\geq 1$. Suppose that the assumptions of D.4 hold. Let $\lambda = \frac{1}{n}$. We assume that $n\geq 1$ satisfies $n\geq A_{\lambda,\tau}$ with $A_{\lambda,\tau}$ defined in Eq. (eq:FS_thm_16_const) and $\tilde{n} \geq 1$ satisfies Eq.~(eq:m_sufficient_large). Then, with $P^{n+\tilde{n}}$-probability $\geq 1-18e^{-\tau}$
    \begin{align*}
        S_{-1} \leq c \tau\sqrt{n}\left(\frac{\left\|\hat{F}_{\xi} -F_\ast \right\|_{\mathcal{G}}}{\sqrt{n}}+\left\| \left[\hat{F}_{\xi}\right] - F_\ast \right\|_{L^2\left(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x}\right)}\right)\left\|\bar{h}_\lambda\right\|_{\mathcal{H}_{FO}} .
    \end{align*}
    where $c$ is a constant independent of $\tilde{n}, n$. Under the same probabilistic event, the bounds in D.4 hold.

Fix $\tau\geq 1$. Suppose that the assumptions of D.4 hold. Let $\lambda = \frac{1}{n}$. We assume that $n\geq 1$ satisfies $n> A_{\lambda,\tau}$ with $A_{\lambda,\tau}$ defined in Eq. (eq:FS_thm_16_const) and $\tilde{n} \geq 1$ satisfies Eq.~(eq:m_sufficient_large). Then, with $P^{n+\tilde{n}}$-probability $\geq 1-10e^{-\tau}$
    \begin{align*}
        S_0 \leq c^{\prime} \tau\sqrt{n}\left(\frac{\left\|\hat{F}_{\xi} -F_\ast \right\|_{\mathcal{G}}}{\sqrt{n}}+\left\| \left[\hat{F}_{\xi}\right] - F_\ast \right\|_{L^2\left(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x}\right)}\right)\left\|\bar{h}_\lambda\right\|_{\mathcal{H}_{FO}},
    \end{align*}
    where $c'$ is a constant independent of $n,\tilde{n}$. Under the same probabilistic event, the bounds in D.4 hold.

Suppose Assumption 2.2 in the main text holds. Suppose $k_{\mathcal{O}}: \mathcal{O}\times\mathcal{O} \to \mathbb{R}$ and $k_{\mathcal{Z}}: \mathcal{Z}\times\mathcal{Z} \to \mathbb{R}$ are Mat\'{e}rn reproducing kernels whose RKHSs $\mathcal{H}_O$ and $\mathcal{H}_Z$ are norm equivalent to $W_2^{t_o}(\mathcal{O})$ and $W_2^{t_z}(\mathcal{Z})$ with $m_o > t_o > d_o/2$, $m_z > t_z > d_z/2$ and $\frac{m_z}{t_z} \wedge \frac{m_o}{t_o} \leq 2$. Define $m^{\dag}=(m_z t_z^{-1}) \wedge (m_o t_o^{-1})$ and $d^{\dag}= (d_z t_z^{-1}) \vee(d_o t_o^{-1})$. 
For $\zeta > 0$ arbitrarily small, we take $\xi = \tilde{n}^{-\frac{1}{m^{\dag} + d^{\dag}/2 + \zeta}}$, then with $P^{\tilde{n}}$-probability at least $1- 4e^{-\tau}$, we have
\begin{align*}
    \left\|\left[\hat{F}_\xi -F_*\right]\right\|_{L^2(\mathcal{Z}\times\mathcal{O}; \mathcal{H}_{X,\gamma_x})} \leq J\tau \tilde{n}^{-\frac{1}{2}\frac{ m^{\dag}}{m^{\dag} + d^{\dag}/2 + \zeta}} , \quad \left\|\hat{F}_\xi -F_*\right\|_{\mathcal{G}} \leq J \tau \tilde{n}^{-\frac{1}{2}\frac{m^{\dag} - 1}{m^{\dag} + d^{\dag}/2 + \zeta}} .
\end{align*}
$J$ is a constant independent of $\tilde{n}$.

Suppose that Assumption 2.2 in the main text is satisfied. Then,
\begin{align*}
    \|F_{\ast}\|_{MW^{m_z, m_o}_2(\mathcal{Z}\times\mathcal{O};\mathcal{H}_{X,\gamma_x})} \leq \sqrt{\binom{m_z + d_z -1}{d_z -1}} \sqrt{ \binom{m_o + d_o-1}{d_o -1}} \rho.
\end{align*}

Suppose the eigenvalues of the operator $\Sigma_1$ satisfy $\mu_{1, i} \asymp i^{-1/p_1}$ and the eigenvalues of the operator $\Sigma_2$ satisfy $\mu_{2, i} \asymp i^{-1/p_2}$. Then the eigenvalues of their tensor product $\Sigma_1 \otimes \Sigma_2$ satisfy, for any $\zeta > 0$,
\begin{align*}
    \lambda_{i}(\Sigma_1 \otimes \Sigma_2) \leq i^{- 1/ p_1 \wedge 1/ p_2  + \zeta}.
\end{align*}

Suppose Assumptions~4.3, 4.2, 4.1, 2.3, 2.2 hold. Let $\lambda \asymp n^{-1}$ and 
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*}
Then, with $P^n$-probability $\geq 1-  4e^{-\tau}$, for sufficiently large $n\geq 1$, we have
\begin{align*}
    \left\|T\left(f_{\ast} - \left[\bar{f}_{\lambda}\right]\right)\right\|_{L^2(P_{ZO})} \leq  2C\tau (\log n)^{\frac{d_x+d_o+1}{2}} n^{-\frac{\frac{s_x}{d_x}+\eta_1}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}
\end{align*}
for some constant $C>0$ independent of $n$.

Let $\mathcal{X} = [0,1]^d$. Let $f : \mathbb{R}^{d} \to \mathbb{R}$ and $f \in B_{2,q}^{\boldsymbol{s}}(\mathcal{X}) \cap L^1(\mathbb{R}^d)$ with $\boldsymbol{s} = [s_1, \ldots, s_d]^\top$. Recall $K_{\boldsymbol{\gamma}}$ defined in Eq. (eq:K_function) with $\boldsymbol{\gamma} = [\gamma_1, \ldots, \gamma_d]^\top \in (0,1]^d$.  Then, we have 
\begin{align*}
    \left\|\left[K_{\boldsymbol{\gamma}}\ast f\right] - f\right\|_{L^2(\mathcal{X})} \leq C_0 |f|_{B_{2,q}^{\boldsymbol{s}}(\mathcal{X})} \cdot \max\{\gamma_1^{s_1}, \ldots, \gamma_d^{s_d}\} 
\end{align*}
for some constant $C_0$ that only depends on $d, \boldsymbol{s}$.

Suppose Assumptions~2.2, 2.3, 4.1, 4.2 and 4.3 in the main text hold. 
Let $\lambda \asymp n^{-1}$ and 
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*} With $P^n$-probability $\geq 1-  4e^{-\tau}$, for sufficiently large $n\geq 1$, we have
\begin{align*}
\left\|T\left(\left[\bar{f}_{\lambda}\right] - [f_{\lambda}]]\right)\right\|_{L^2(P_{ZO})}^2 \leq C \tau^2 n^{-\frac{2(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} (\log n)^{d_x+d_o+1},
\end{align*}
for some constant $C$ independent of $n$.

Suppose 2.2 hold, and let
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align*}
Then, for sufficiently large $n\geq 1$, we have 
\begin{align*}
    \|C_{FO}\| \geq a\left(\frac{\sqrt{\pi}}{4}\right)^{\frac{d_x+d_o}{2}} n^{-\frac{1}{2}\frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} .
\end{align*}

Let $n\geq 10$ and $\lambda=n^{-1}$. Let $\gamma_x,\gamma_o\in (0,1]$ be the lengthscales for the RKHS $\mathcal{H}_{\gamma_x,\gamma_o}$. Suppose that the distribution $P_{XO}$ satisfies Assumption~2.2. Then we have,
    \begin{align*}
        \mathcal{N}_{FO}(\lambda) \leq C'(\log n)^{d_x+d_o+1} \left(\gamma_x^{d_x}\gamma_o^{d_o}\right)^{-1}
    \end{align*}
    for some constant $C'$ independent of $n, \gamma_x,\gamma_o$.

Suppose Assumption~2.2 holds, and let $m_o,m_z,\rho$ be as defined in the statement of Assumption~2.2. Suppose $\theta\in (0,1)$ satisfies  $\frac{d_o}{2m_o\theta} < 1$ and $\frac{d_z}{2m_z\theta} < 1$. Then there exists a constant $C_{\theta}>0$ independent of $n$ such that 
\begin{align*}
    \left\|k_{FO}^{\theta}\right\|_{\infty} 
    := \left\|[\mathcal{H}_{FO}]^{\theta}_{P_{ZO}}\hookrightarrow L^{\infty}(P_{ZO})\right\|\lesssim  C_{\theta} \rho^{\theta}\gamma_o^{-\theta m_o}.
\end{align*}

Suppose Assumptions~2.2, 4.4 hold with parameters $m_z, m_o \in \mathbb{N}^{+}$, Assumption~2.3 holds with parameters $s_x, s_o > 0$, Assumptions~4.2, 4.3 hold with parameters $\eta_0, \eta_1$. We further suppose Assumptions~4.1 and 4.5 hold. We assume $t_o, t_z$ satisfy $2t_o \geq m_o > t_o > d_o/2$, $2 t_z \geq m_z > t_z > d_z/2$. We let
\begin{align}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}}, \quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align}  Define $m^{\dag} := (m_z t_z^{-1}) \wedge (m_o t_o^{-1})$ and $d^{\dag} := (d_z t_z^{-1}) \vee (d_o t_o^{-1})$. 
Let Stage I regularization parameter $\xi$ be given by $\tilde{n}^{-\frac{1}{m^{\dag} + d^{\dag} + \zeta}}$ for any $\zeta>0$; and Stage II regularization parameter $\lambda$ be given by $n^{-1}$. Suppose that $n\geq 1$ is sufficiently large, and $\tilde{n} \geq 1$ satisfies
\begin{align}
\begin{aligned}
    \tilde{n} \gtrsim n^{\frac{m^{\dag} + d^{\dag}/2 + \zeta}{m^{\dag}-1}} \vee n^{2 \frac{m^{\dag} + d^{\dag}/2 + \zeta}{m^{\dag}}}.
\end{aligned}
\end{align}
Then with $P^{n+\tilde{n}}$-probability at least $1-  40e^{-\tau}$, we have
\begin{align}

    \left\|\left[\hat{f}_{\lambda}\right] - f_{\ast}\right\|_{L^2(P_{XO})} \lesssim \tau n^{-\frac{\frac{s_x}{d_x}+\eta_1-\eta_0}{1+2(\frac{s_x}{d_x}+\eta_1)+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}} \cdot (\log n)^{\frac{d_x+d_o+1+d_x\eta_0}{2}} .
\end{align}

\begin{align}
    &\quad \|f_{\mathrm{aux}}\|_{\mathcal{H}_{\gamma_x,\gamma_o}} 
    \\ &\leq \left\| f_{\ast} \ast K_{\gamma_o} \ast \mathcal{F}^{-1}[\iota_{x, \gamma_x^{-1}}] \right\|_{\mathcal{H}_{\gamma_x,\gamma_o}} + \left\| K_{\gamma_x} \ast K_{\gamma_o} \ast (f_{\ast} - f_{\ast, \mathrm{low}}) \right\|_{\mathcal{H}_{\gamma_x,\gamma_o}}  \\
    &\stackrel{(a)}{\leq} n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f_\ast\|_{L^2(\mathbb{R}^{d_x+d_o})} + n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}
    \|f_{\ast} - f_{\ast,\mathrm{low}} \|_{L^2(\mathbb{R}^{d_x+d_o})}   \\
    &\stackrel{(b)}{\leq}  3 n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align}

Given a function $f:\mathbb{R}^{d}\to\mathbb{R}$, we have
\begin{align*}
    \left\|K_{\boldsymbol{\gamma}}\ast f \right\|_{\mathcal{H}_{X,\boldsymbol{\gamma}}} \leq \left(\prod_{i=1}^{d}\gamma_i^{-\frac{1}{2}}\right)\pi^{-\frac{d}{4}}(2^r - 1)\|f\|_{L^2(\mathbb{R}^d)}.
\end{align*}

Let $f:\mathbb{R}^{d_x+d_o}\to \mathbb{R}$ and 
    \begin{align*}
        \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}},\quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
    \end{align*}
    Recall $K_{\gamma_x}:\mathbb{R}^{d_x} \to \mathbb{R}$ and $K_{\gamma_o}:\mathbb{R}^{d_o} \to \mathbb{R}$ defined in Eq.~(eq:K_function), then we have
    \begin{align*}
        \|K_{\gamma_x} \ast K_{\gamma_o} \ast f\|_{\mathcal{H}_{\gamma_x,\gamma_o}} \leq C_{1} 
        n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}
        \|f\|_{L^2(\mathbb{R}^{d_x+d_o})},
    \end{align*}
    for some constant $C_1$ that only depends on $d_x,d_o,s_x,s_o$.

Let $\gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}$, $\gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}$. 
    Let $\iota_{x,\gamma_x^{-1}} : \mathbb{R}^{d_x} \to \mathbb{R}$ be an indicator function over $\{\boldsymbol{\omega}_x: \|\boldsymbol{\omega}_x\|_2 \leq \gamma_x^{-1} \}$ and $K_{\gamma_o}: \mathbb{R}^{d_x} \to \mathbb{R}$ be as defined in Eq.~(eq:K_function).
    Then we have
    \begin{align*}
        \|\mathcal{F}^{-1}[\iota_{x,\gamma_x^{-1}}] \ast K_{\gamma_o} \ast f\|_{\mathcal{H}_{\gamma_x,\gamma_o}} \lesssim 2^{r} n^{\frac{1}{2} \frac{1+\frac{d_o}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}} \|f\|_{L^2(\mathbb{R}^{d_x+d_o})} .
    \end{align*}

Suppose that 4.2 in the main text holds, and suppose $\gamma_x^{\delta_x} = \gamma_o^{\delta_o}$ for some positive constant $\delta_x, \delta_o$. 
Suppose $f\in \mathcal{H}_{\gamma_x,\gamma_o}$ with $\|f\|_{\mathcal{H}_{\gamma_x,\gamma_o}}^2 \leq Cn$ for some constant $C>0$. Then,
\begin{align}
    \|f\|_{L^2(P_{XO})} &\lesssim \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}} \|Tf\|_{L^2(P_{ZO})}  \\
    &\qquad + \gamma_x^{-d_x\eta_0} (\log (\gamma_x^{-\delta_x}))^{\frac{d_x\eta_0}{2}}\gamma_x^{\frac{1}{8} \delta_x} (n \gamma_x^{d_x}\gamma_o^{d_o})^{\frac{1}{2}}  .
\end{align}
In particular, for 
\begin{align*}
    \gamma_x = n^{-\frac{\frac{1}{d_x}}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}},\quad \gamma_o = n^{-\frac{\frac{1}{s_o}(\frac{s_x}{d_x}+\eta_1)}{1+(2+\frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}. 
\end{align*}
and $\frac{1}{8} \delta_x = 2s_x + d_x\eta_1 + d_x \eta_0$, $\delta_x = \delta_o \frac{d_x}{s_o}(\frac{s_x}{d_x}+\eta_1)$. 
Then, we have
\begin{align*}
    \|f\|_{L^2(P_{XO})} \lesssim \gamma_x^{-d_x\eta_0} (\log n)^{\frac{d_x\eta_0}{2}} \|Tf\|_{L^2(P_{ZO})} + n^{-\frac{\frac{s_x}{d_x} }{1+(2 + \frac{d_o}{s_o})(\frac{s_x}{d_x}+\eta_1)}}.
\end{align*}

Let $\boldsymbol{\gamma} = (\gamma_1,\dots,\gamma_d)\in (0,1)^{d}$. Let $k_{\boldsymbol{\gamma}}$ be the anisotropic Gaussian kernel on $\mathbb{R}^d$ and let $\mathcal{H}_{X,\boldsymbol{\gamma}}$ be the RKHS associated with $k_{\boldsymbol{\gamma}}$. Then 
\begin{align*}
    \int_{\mathbb{R}^{d}} |\mathcal{F}[f](\boldsymbol{\omega})|^2\exp\left(\frac{\|\boldsymbol{\omega}\odot \boldsymbol{\gamma}\|_{2}^{2}}{4}\right) \;\mathrm{d}\boldsymbol{\omega} = 2^{d} \pi^{d/2} \left(\prod_{i=1}^{d} \gamma_i\right) \|f\|_{\mathcal{H}_{X,\boldsymbol{\gamma}}}^2
\end{align*}
